diff --git a/src/log.ts b/src/log.ts
index 4892c8b..f248749 100644
--- a/src/log.ts
+++ b/src/log.ts
@@ -1,3 +1,18 @@
+let queue: string[] = [];
+let scheduled = false;
+
+const flush = (): void => {
+  if (queue.length === 0) return;
+  const batch = queue;
+  queue = [];
+  scheduled = false;
+  process.stdout.write(batch.join(''));
+};
+
 export const log = (message: string): void => {
-  process.stdout.write(`${JSON.stringify({ message })}\n`);
+  queue.push(`${JSON.stringify({ message })}\n`);
+  if (!scheduled) {
+    scheduled = true;
+    setImmediate(flush);
+  }
 };
